    if(Array.isArray(s.rows))s.rows.forEach(r=>{if(r.changes)diffs(r.rowKey,r.changes);else lines.push((r.rowKey||r.productCode||'')+' · '+(r.cartonCount??r.actual??'')+' thùng')});
