    if(s.previousKey)lines.push(s.previousKey+' → '+s.remaining?.rowKey+' + '+s.created?.rowKey+' · Chi phí hai nhánh cần nhập lại');
    if(s.from!==undefined)lines.push(name(s.from)+' → '+name(s.to));if(s.date)lines.push('Ngày về: '+s.date+' · Kho: '+s.warehouse);if(s.loading)lines.push('Lịch bốc: '+s.loading);if(s.counts)lines.push('Thêm '+s.counts.create+' · Sửa '+s.counts.update+' · Giữ '+s.counts.unchanged);if(s.row)lines.push(s.row.productCode+' · '+s.row.cartonCount+' thùng');
